const HEADER = 'date,description,amount,category';

export function parseCSV(text) {
  if (!text || !text.trim()) {
    return [];
  }

  const rows = [];
  let row = [];
  let currentField = '';
  let inQuotes = false;
  const pushRow = () => { row.push(currentField); rows.push(row); row = []; currentField = ''; };
  text = String(text).replace(/^\uFEFF/, '');
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inQuotes) {
      if (ch === '"') {
        if (text[i + 1] === '"') { currentField += '"'; i++; }
        else inQuotes = false;
      } else currentField += ch;
    } else if (ch === '"' && currentField === '') inQuotes = true;
    else if (ch === ',') { row.push(currentField); currentField = ''; }
    else if (ch === '\n') pushRow();
    else if (ch !== '\r') currentField += ch;
  }
  if (currentField !== '' || row.length || (text && !/[\r\n]$/.test(text))) pushRow();

  if (rows.length === 0) {
    return [];
  }

  // Check if first row is header
  let startIndex = 0;
  const firstRow = rows[0].map((c) => c.trim().toLowerCase());
  if (
    firstRow.length >= 4 &&
    firstRow[0] === 'date' &&
    firstRow[1] === 'description' &&
    firstRow[2] === 'amount' &&
    firstRow[3] === 'category'
  ) {
    startIndex = 1;
  }

  const items = [];
  for (let r = startIndex; r < rows.length; r++) {
    const row = rows[r];
    if (row.length === 1 && row[0] === '') {
      continue;
    }
    const [date = '', description = '', amountStr = '0', category = ''] = row;
    items.push({
      date,
      description,
      amount: Number(amountStr),
      category,
    });
  }

  return items;
}

function escapeCSVField(value) {
  const str = value == null ? '' : String(value);
  if (
    str.includes(',') ||
    str.includes('"') ||
    str.includes('\n') ||
    str.includes('\r')
  ) {
    return '"' + str.replace(/"/g, '""') + '"';
  }
  return str;
}

export function toCSV(items) {
  const lines = [HEADER];
  for (const item of items || []) {
    const row = [
      escapeCSVField(item.date),
      escapeCSVField(item.description),
      escapeCSVField(item.amount),
      escapeCSVField(item.category),
    ];
    lines.push(row.join(','));
  }
  return lines.join('\n');
}
function parseYMD(dateStr) {
  const [y, m, d] = dateStr.split('-').map(Number);
  return { y, m, d };
}

function formatYMD(y, m, d) {
  const ys = String(y).padStart(4, '0');
  const ms = String(m).padStart(2, '0');
  const ds = String(d).padStart(2, '0');
  return `${ys}-${ms}-${ds}`;
}

function daysInMonth(year, month) {
  return new Date(Date.UTC(year, month, 0)).getUTCDate();
}

export function expandRecurring(rule, until) {
  if (!rule || !rule.date) return [];
  const { date, description, amount, category, every } = rule;

  if (!until || date > until) {
    return [];
  }

  const results = [];

  if (every === 'week') {
    const { y, m, d } = parseYMD(date);
    let current = new Date(Date.UTC(y, m - 1, d));
    while (true) {
      const curStr = formatYMD(
        current.getUTCFullYear(),
        current.getUTCMonth() + 1,
        current.getUTCDate()
      );
      if (curStr > until) break;
      results.push({
        date: curStr,
        description,
        amount: Number(amount),
        category,
      });
      current.setUTCDate(current.getUTCDate() + 7);
    }
  } else if (every === 'month') {
    const { y: startY, m: startM, d: startD } = parseYMD(date);
    let step = 0;
    while (true) {
      const totalMonths = startM - 1 + step;
      const curY = startY + Math.floor(totalMonths / 12);
      const curM = (totalMonths % 12) + 1;
      const maxD = daysInMonth(curY, curM);
      step++;
      const curStr = formatYMD(curY, curM, Math.min(startD, maxD));
      if (curStr > until) break;
      results.push({
        date: curStr,
        description,
        amount: Number(amount),
        category,
      });
    }
  } else {
    results.push({
      date,
      description,
      amount: Number(amount),
      category,
    });
  }

  return results;
}
